import {redlineBadge,redlinePanel,redlineChecklist} from './redline-ui.js';
import {reportScore,scoreLabel} from './report-score.js';
import {VERSION,RULE_VERSION,extract,compare,validFeature,initialize} from './engine.js';
import {TEMPLATE_CATEGORIES,ALL_CATEGORIES,UNCATEGORIZED} from './categories.js';
import {composeTemplateName,templateNameParts} from './template-name.js';
import {SHARED_API} from './shared-config.js';
import {referenceUpdateTargets} from './reference-update.js';
import {createUploadPipeline} from './upload-pipeline.js';
import {retryReviewItem,loadRetryVideo} from './retry-review.js';
import {categoryTemplates,templateState,selectedEnabledTemplate,categoryPreparationTargets} from './template-picker.js';
const retryRequests=new Set(),referenceTasks=new Map(),referenceErrors=new Map(),referenceProgress=new Map();
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let db,templates=[],records=[],queue=[],busy=false,stop=false,mode='check',progress='',filter='',search='',dayFilter='all';
let member='';
let preparationTail=Promise.resolve(),pendingPreparations=0,preparingTemplateIds=new Set(),referenceBatchRunning=false,referenceUpdateMessage='';
let selectedCategory='',selectedTemplateId='',libraryCategory='all',newTemplateCategory='',recordCategory='';
const categoryOptions=(selected,placeholder='请选择模板分类')=>'<option value="">'+placeholder+'</option>'+ALL_CATEGORIES.map(c=>'<option value="'+esc(c)+'" '+(selected===c?'selected':'')+'>'+esc(c)+'</option>').join('');
function chosenTemplate(){return selectedEnabledTemplate(templates,selectedCategory,selectedTemplateId);}

let localRecords=[],sharedReady=false,sharedError='',recordTotal=0,hasMore=false,sharedStats={total:0,pass:0,fail:0,review:0},requestEpoch=0,searchTimer,bgmTarget=null;
let deviceToken=localStorage.getItem('yingtie-shared-owner');
if(!/^[a-f0-9]{64}$/.test(deviceToken||'')){deviceToken=Array.from(crypto.getRandomValues(new Uint8Array(32)),n=>n.toString(16).padStart(2,'0')).join('');localStorage.setItem('yingtie-shared-owner',deviceToken);}
try{member=(localStorage.getItem('clipguard-member')||'').trim().slice(0,30);}catch{}
const today=()=>new Date().toLocaleDateString('sv-SE',{timeZone:'Asia/Shanghai'});
const day=s=>new Date(s).toLocaleDateString('sv-SE',{timeZone:'Asia/Shanghai'});
const dateText=s=>new Date(s).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false});
const label={pass:'通过',fail:'不通过',review:'待复核'};
const badge=s=>'<span class="badge '+(s==='fail'?'fail':s==='review'?'review':'')+'">'+label[s]+'</span>';
const score=v=>v==null?'—':v.toFixed(1)+'%';
const route=()=>location.hash.slice(1)||'workbench';
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('visible'),4500);}
function put(store,item){return new Promise((res,rej)=>{const tx=db.transaction(store,'readwrite');tx.objectStore(store).put(item);tx.oncomplete=()=>res();tx.onerror=()=>rej(tx.error);tx.onabort=()=>rej(tx.error||new Error('存储写入中止'));});}
function remove(store,id){return new Promise((res,rej)=>{const tx=db.transaction(store,'readwrite');tx.objectStore(store).delete(id);tx.oncomplete=res;tx.onerror=()=>rej(tx.error);});}
function all(store){return new Promise((res,rej)=>{const r=db.transaction(store).objectStore(store).getAll();r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error);});}
async function init(){try{db=await new Promise((res,rej)=>{const r=indexedDB.open('clipguard-v1',1);r.onupgradeneeded=()=>{r.result.createObjectStore('templates',{keyPath:'id'});r.result.createObjectStore('records',{keyPath:'id'});};r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error);});localRecords=(await all('records')).map(r=>({...r,localOnly:true}));render();if(!member)showMemberPrompt();await refreshShared(true);setInterval(()=>{if(!document.hidden&&!busy)refreshShared(false);},30000);}catch(e){sharedError=e.message;render();toast('共享区加载失败：'+e.message);}}

async function apiCall(path,options={}){
 const headers=new Headers(options.headers||{});headers.set('X-Owner-Token',deviceToken);
 let payload=options.body;if(payload&&!(payload instanceof Blob)&&!(payload instanceof ArrayBuffer)&&typeof payload!=='string'){headers.set('Content-Type','application/json');payload=JSON.stringify(payload);}
 const response=await fetch(SHARED_API+path,{...options,headers,body:payload,cache:'no-store'});
 let data;try{data=await response.json();}catch{throw new Error('共享后台响应异常');}if(!response.ok)throw new Error(data.error||'共享请求失败');return data;
}
function recordsQuery(offset=0){const q=new URLSearchParams({offset:String(offset)});if(search)q.set('search',search);if(filter)q.set('status',filter);if(dayFilter==='today')q.set('day','today');if(recordCategory)q.set('category',recordCategory);return '/api/records?'+q;}
async function refreshShared(reset=false){
 const epoch=++requestEpoch;try{const [a,b,c]=await Promise.all([apiCall('/api/templates'),apiCall(recordsQuery()),apiCall('/api/stats')]);if(epoch!==requestEpoch)return;templates=a.templates.map(t=>({...t,category:t.category||UNCATEGORIZED}));const map=new Map((reset?[]:records).map(r=>[r.id,r]));for(const r of b.records)map.set(r.id,{...r,shared:true});records=[...map.values()].sort((a,b)=>a.createdAt.localeCompare(b.createdAt));recordTotal=b.total;hasMore=records.length<recordTotal;sharedStats=c;sharedReady=true;sharedError='';if(!document.activeElement?.matches('input,select,textarea'))render();else if($('#records-table')){$('#records-table').innerHTML=recordTable(filteredRecords());if($('#filtered-count'))$('#filtered-count').textContent=records.length+' / '+recordTotal+' 条';}}catch(e){if(epoch!==requestEpoch)return;sharedReady=false;sharedError=e.message;if(!document.activeElement?.matches('input,select,textarea'))render();}}
async function loadMore(){const data=await apiCall(recordsQuery(records.length));const map=new Map(records.map(r=>[r.id,r]));for(const r of data.records)map.set(r.id,{...r,shared:true});records=[...map.values()].sort((a,b)=>a.createdAt.localeCompare(b.createdAt));recordTotal=data.total;hasMore=records.length<recordTotal;render();}
function videoURL(path){return path?.startsWith('/api/videos/')?SHARED_API+path:'';}
function syncNotice(){return '<div class="notice shared-notice '+(sharedError?'sync-error':'')+'"><span><strong>全组公开共享</strong> · 新上传的视频和审核结果，所有人均可查看。'+(sharedError?' 连接失败：'+esc(sharedError):sharedReady?' 每30秒自动同步；各自上传审核独立进行。':' 正在连接共享后台…')+'</span><button class="btn secondary small" data-action="refresh-shared">刷新共享区</button></div>';}
function recordBadge(r){return r.state==='uploading'?'<span class="badge review">上传中</span>':r.state==='processing'?'<span class="badge review">检测中</span>':r.state==='failed'?'<span class="badge fail">上传失败</span>':r.algorithm&&r.algorithm!==RULE_VERSION?'<span class="badge review">旧结果：'+label[r.status]+'</span>':badge(r.status);}

function download(data,name,type){const url=URL.createObjectURL(new Blob([data],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function pageHead(eyebrow,title,description,action=''){return'<div class="page-head"><div><div class="eyebrow">'+eyebrow+'</div><h1>'+title+'</h1><p>'+description+'</p></div>'+action+'</div>';}
function stats(){return'<div class="stats">'+[['全组今日上传',sharedStats.total||0,'条','▦','所有组员的共享视频',''],['检测通过',sharedStats.pass||0,'条','✓','任一有效项不超过 70%','green-text'],['需要修改',sharedStats.fail||0,'条','↗','可比项目均超过 70%','orange-text'],['待复核与处理中',sharedStats.review||0,'条','◷','识别缺失或尚未处理完','']].map(x=>'<div class="stat"><div class="stat-label">'+x[0]+'</div><span class="stat-icon">'+x[3]+'</span><div class="stat-num '+x[5]+'">'+x[1]+'<small>'+x[2]+'</small></div><div class="stat-caption">'+x[4]+'</div></div>').join('')+'</div>';}
function ruleCard(){return'<div class="card"><div class="card-head"><h2>本次检测标准</h2><span class="pill">证据校验 v2</span></div><div class="card-body"><div class="rule-title">通过线 · 不超过（含70%）</div><div class="threshold"><strong>70</strong><span>%</span></div><div class="threshold-bar"></div><div class="bar-labels"><span>0% · 低重复</span><span>100% · 高重复</span></div><div class="rule-row"><span>任一有效项不超过 70%</span>'+badge('pass')+'</div><div class="rule-row"><span>可比项目全部超过 70%</span>'+badge('fail')+'</div><div class="rule-row"><span>无通过项且仍有识别缺项</span>'+badge('review')+'</div><div class="rule-note">只与所选模板比对。画面、字幕、花字、BGM任一有效项不超过70%即通过，口播不计分。<br>无内容或未识别的项目不会凭空记为0%。</div></div></div><div class="mini-card"><h3>先建立你的内容基准</h3><p>上传参考视频到共享模板库，组员先选择分类和对应模板，再上传检测。</p><a href="#templates">前往视频模板库 ↗</a></div>';}
function uploadCard(){
 const items=categoryTemplates(templates,selectedCategory),selected=chosenTemplate(),pending=categoryPreparationTargets(templates,selectedCategory),ready=items.filter(t=>t.enabled!==false&&t.featureReady).length;
 let note=!selectedCategory?'先选择分类和对应模板，再添加待检测视频。':!items.length?'该分类尚未上传模板，请先添加参考模板。':'该分类已有 '+items.length+' 个模板，'+ready+' 个可立即检测。选择待准备或需更新的模板，会自动准备参考。';
 if(selected)note='已选：'+selectedCategory+' / '+selected.name+'。'+(selected.featureReady?'本次添加的视频只对比此模板。':'可先添加待检测视频，参考准备完成后自动开始上传审核。');
 return '<div class="card"><div class="card-head"><h2>选择对应模板，上传视频</h2><small>仅对比所选模板</small></div><div class="card-body"><div class="template-picker"><label>① 选择模板分类<select id="upload-category">'+categoryOptions(selectedCategory)+'</select></label><label>② 选择对应模板<select id="upload-template" '+(!selectedCategory||!items.length?'disabled':'')+'><option value="">'+(!selectedCategory?'请先选择分类':items.length?'请选择对应模板（含待准备参考）':'该分类尚未上传模板')+'</option>'+items.map(t=>'<option value="'+esc(t.id)+'" '+(selectedTemplateId===t.id?'selected':'')+' '+(t.enabled===false?'disabled':'')+'>'+esc(t.name+' · '+templateState(t))+'</option>').join('')+'</select></label></div><p class="selection-note" role="status">'+esc(note)+'</p>'+(pending.length?'<button class="btn secondary small" data-action="prepare-category-references" '+(referenceBatchRunning?'disabled':'')+'>准备 / 更新本分类参考（'+pending.length+'）</button>':'')+'<p id="reference-progress" role="status">'+esc(selected?(referenceErrors.get(selected.id)||referenceProgress.get(selected.id)||''):'')+'</p>'+(referenceUpdateMessage?'<div class="notice" role="status">'+esc(referenceUpdateMessage)+'</div>':'')+'<div class="dropzone" id="dropzone" role="button" tabindex="0" aria-label="选择或拖入视频" aria-disabled="'+!selected+'"><div class="upload-icon">↥</div><h3>③ 上传待检测视频</h3><p>支持多选或拖入；审核进行中也可继续添加，上传无需等待上一条审核</p><button class="btn" data-action="choose" '+(!selected?'disabled':'')+'>'+(busy?'＋ 继续添加视频（可多选）':'＋ 批量选择视频')+'</button><p class="support">MP4 / MOV均支持 · 支持批量选择 · 不设文件大小、时长或数量上限</p></div><div class="upload-options"><div class="member member-assigned"><span>提交组员</span><strong>'+esc(member||'尚未填写')+'</strong><span class="member-auto">自动识别</span><button class="member-switch" data-action="switch-member">切换</button></div><span>◈ 画面 + 字幕 + 花字 + BGM</span></div><div id="queue">'+queueHTML()+'</div></div></div>';
}

function previewTemplateName(q){try{return composeTemplateName(q.hitName,q.personalName);}catch{return'请填写个人名字';}}
function templateQueueHTML(){return'<div class="section-spacer"><div class="notice">模板无需审核。只需按“爆款名字+个人名字”命名后直接入库，爆款名字按所选分类固定，个人名字默认当前姓名，可以修改。</div>'+queue.map((q,i)=>'<div class="queue-item"><div class="queue-row"><span>▹ '+esc(q.file.name)+'</span><small>'+esc(q.state)+'</small>'+(!busy&&!q.done?'<button class="btn ghost small" data-action="remove-queue" data-id="'+i+'" aria-label="移除模板">×</button>':'')+'</div><p class="queue-template">所属分类：'+esc(q.category)+'</p><div class="template-rename-fields"><label>爆款名字（固定）<input type="text" value="'+esc(q.hitName)+'" readonly></label><span class="name-plus">＋</span><label>个人名字（可修改）<input data-template-person="'+i+'" type="text" maxlength="30" value="'+esc(q.personalName)+'" placeholder="请输入个人名字" '+(busy||q.done?'disabled':'')+'></label></div><p class="template-name-preview">最终模板名：<strong id="template-name-preview-'+i+'">'+esc(previewTemplateName(q))+'</strong></p></div>').join('')+(busy?'<p id="progress-text" role="status">'+esc(progress)+'</p>':'')+'<div class="queue-actions">'+(busy?'<button class="btn secondary" data-action="stop">停止后续上传</button>':'<button class="btn secondary" data-action="clear-queue">清空队列</button><button class="btn" data-action="run">'+(queue.every(q=>q.done)?(queue.some(q=>q.failed)?'上传已结束':'全部已入库'):'上传并直接入库')+'</button>')+'</div><p class="selection-note">上传成功后，系统自动准备查重参考。准备期间请保持页面打开；这不是审核，不需要确认BGM、字幕或花字。</p></div>';}
function queueHTML(){if(!queue.length)return'';if(mode==='template')return templateQueueHTML();return'<div class="section-spacer"><div class="notice personal-queue-note"><strong>我的上传与审核队列 · 仅当前页面</strong><br>其他组员可同时上传审核。停止、清空本页队列不会操作他人的任务。支持批量上传；审核期间可继续添加，上传与审核独立排队。开始上传后会固定对应模板，不受后续模板修改影响。</div><div class="notice">画面、字幕、花字、BGM任一有效项≤70%即通过，口播不参与。混有口播的视频请另选与视频同起止的纯BGM片段；未提供时BGM不计分，其他有效项仍可决定通过。纯BGM仅在本机生成指纹。</div>'+('<div class="queue-actions"><button class="btn secondary small" data-action="batch-no-bgm">未审核项均无BGM</button><button class="btn secondary small" data-action="batch-bgm">未审核项使用同一纯BGM片段</button></div>')+queue.map((q,i)=>'<div class="queue-item"><div class="queue-row"><span title="'+esc(q.file.name)+'">▹ '+esc(q.file.name)+'</span><small>'+esc(q.state||'等待检测')+'</small>'+(!q.started||q.done?'<button class="btn ghost small" data-action="remove-queue" data-id="'+i+'" aria-label="移除视频">×</button>':'')+'</div><p class="queue-template">'+(mode==='template'?'加入分类：'+esc(q.category):'对应模板：'+esc(q.category)+' / '+esc(q.templateName))+'</p><div class="queue-evidence"><label>BGM <select data-bgm="'+i+'" '+(q.auditing||q.done?'disabled':'')+'><option value="review" '+(q.bgmMode==='review'?'selected':'')+'>未确认 · 待复核</option><option value="none" '+(q.bgmMode==='none'?'selected':'')+'>确认没有BGM</option><option value="file" '+(q.bgmMode==='file'?'selected':'')+'>使用纯BGM音频片段</option></select></label>'+(q.bgmMode==='file'?'<button class="btn secondary small" data-action="pick-bgm" data-id="'+i+'" '+(q.auditing||q.done?'disabled':'')+'>'+esc(q.bgmFile?.name||'选择纯BGM片段')+'</button>':'')+'<label><input type="checkbox" data-no-subtitle="'+i+'" '+(q.noSubtitle?'checked':'')+' '+(q.auditing||q.done?'disabled':'')+'> 确认无字幕</label><label><input type="checkbox" data-no-overlay="'+i+'" '+(q.noOverlay?'checked':'')+' '+(q.auditing||q.done?'disabled':'')+'> 确认无花字</label></div></div>').join('')+(busy?'<div class="progressbox"><p id="progress-text" role="status">'+esc(progress)+'</p><div class="progress"><i style="width:'+Math.round(queue.filter(q=>q.done).length/queue.length*100)+'%"></i></div></div>':'')+'<div class="queue-actions">'+(busy?'<button class="btn secondary" data-action="stop">'+(stop?'已上传视频继续审核，之后停止':'停止后续上传（已上传继续审核）')+'</button>':'<button class="btn secondary" data-action="clear-queue">清空队列</button><button class="btn" data-action="run">'+(queue.every(q=>q.done)?'全部已处理':mode==='template'?'提取并加入模板库':'开始批量上传与审核')+'</button>')+'</div></div>';}
function retryReviewButton(r){if(!r.videoUrl||r.localOnly)return '';const pending=retryRequests.has(r.id)||queue.some(q=>q.retrySourceId===r.id&&!q.done);return '<button class="btn ghost small" data-action="retry-review" data-id="'+esc(r.id)+'" '+(pending?'disabled':'')+' title="读取已上传原视频，生成新的审核记录">'+(pending?'重审排队中…':'↻ 重新审核')+'</button>';}
async function retryReview(id){
 if(retryRequests.has(id)||queue.some(q=>q.retrySourceId===id&&!q.done))return toast('这条视频已在本页重审队列中');
 if(mode==='template'&&(busy||queue.some(q=>!q.done)))return toast('请先完成当前模板上传，再重新审核视频');
 if(checkPipeline.stopping&&checkPipeline.running)return toast('当前队列正在停止，请完成后再重新审核');
 retryRequests.add(id);render();
 try{const r=await apiCall('/api/records/'+id),list=await apiCall('/api/templates'),t=list.templates.find(t=>t.id===r.selectedTemplateId),q=retryReviewItem(r,t,{member,localItem:queue.find(q=>q.sharedId===r.id)});q.retryVideoUrl=videoURL(r.videoUrl);templates=list.templates;if(!chosenTemplate()){selectedCategory=t.category;selectedTemplateId=t.id;}if(mode==='template')queue=[];mode='check';queue.push(q);location.hash='workbench';if($('#detail').open)$('#detail').close();render();toast('已加入重新审核队列，原记录保留，结果将显示为“重审”新记录');if(checkPipeline.running)checkPipeline.wake();else void run();}
 catch(e){toast('无法重新审核：'+e.message);}
 finally{retryRequests.delete(id);render();}
}
function recordTable(items,full=false){if(!items.length)return'<div class="empty"><div class="empty-icon">▤</div><strong>'+ (sharedReady?'全组尚无匹配的视频':'正在连接共享视频库')+'</strong>同事上传后，视频、姓名和检测结果会在这里共享</div>';return'<div class="table-wrap"><table><thead><tr><th>视频文件</th><th>上传组员</th><th>对应模板</th><th>最高检测分项</th><th>查重状态 / 红线提示</th><th>视频与报告</th></tr></thead><tbody>'+items.map(r=>'<tr><td><div class="file-cell">'+(r.thumbnail?'<img class="thumb" src="'+esc(r.thumbnail)+'" alt="">':'<span class="thumb shared-thumb">▷</span>')+'<div><span class="file-name" title="'+esc(r.name)+'">'+esc(r.name)+'</span><div class="file-sub">'+dateText(r.createdAt)+(r.algorithm&&r.algorithm!==RULE_VERSION?' · 旧版识别':'')+(r.duration?' · '+r.duration.toFixed(1)+'s':'')+'</div></div></div></td><td>'+esc(r.member||'未填写')+'</td><td><strong>'+esc(r.category||UNCATEGORIZED)+'</strong><div class="file-sub">'+esc(r.selectedTemplateName||'旧记录 · 全部启用模板')+'</div></td><td><span class="score '+(reportScore(r)>70?'high':'')+'">'+scoreLabel(reportScore(r))+'</span></td><td>'+recordBadge(r)+redlineBadge(r)+'</td><td><button class="btn ghost small" data-action="report" data-id="'+r.id+'">'+(r.videoUrl?'▷ 播放 / 报告':'查看详情')+'</button>'+retryReviewButton(r)+(r.canEdit?'<button class="btn ghost small danger" data-action="delete-shared" data-id="'+r.id+'">删除</button>':'')+'</td></tr>').join('')+'</tbody></table></div>';}
function workbench(){return pageHead('英铁1组 · 视频内容检查','英铁1组批量查重网站','发布之前，先让内容通过自己的标准。','<button class="btn secondary" data-action="export-reports">↓ 导出已加载报告</button>')+syncNotice()+stats()+'<div class="grid"><section>'+uploadCard()+'<div class="card section-spacer"><div class="card-head"><h2>全组最近上传 <span class="pill">最近 5 条</span></h2><a class="btn ghost small" href="#records">全部记录 →</a></div>'+recordTable([...records].reverse().slice(0,5))+'</div><div class="split-note"><span>首次检测需下载识别模型，请保持网络连接。</span><span>云端共享 · 本地识别</span></div></section><aside class="right-column">'+ruleCard()+'</aside></div>';}
function templatesPage(){const items=templates.filter(t=>libraryCategory==='all'||t.category===libraryCategory);return pageHead('YOUR REFERENCE LIBRARY','视频模板库','按图片中的名称分类，组员选择对应模板后上传检测。')+'<div class="notice">模板无需审核。爆款名字按所选分类固定，填写或修改个人名字后直接入库。已有模板可由原上传者修改个人名字或分类；参考特征自动准备。所有人均可更新识别参考，更新一次后全组共用；点击更新会一起处理当前需要升级的旧版模板，已是最新版的跳过。</div>'+(referenceUpdateMessage?'<div class="notice" role="status">'+esc(referenceUpdateMessage)+'</div>':'')+'<div class="category-grid"><button class="category-folder '+(libraryCategory==='all'?'active':'')+'" data-action="library-category" data-category="all"><span>▤</span><strong>全部分类</strong><small>'+templates.length+' 个模板</small></button>'+ALL_CATEGORIES.map(c=>'<button class="category-folder '+(libraryCategory===c?'active':'')+'" data-action="library-category" data-category="'+esc(c)+'"><span>▱</span><strong>'+esc(c)+'</strong><small>'+templates.filter(t=>t.category===c).length+' 个模板</small></button>').join('')+'</div><div class="toolbar template-library-tools"><label>新模板所属分类<select id="template-category" '+(busy?'disabled':'')+'>'+categoryOptions(newTemplateCategory)+'</select></label><button class="btn" data-action="add-template" '+(!newTemplateCategory||busy?'disabled':'')+'>＋ 上传参考模板</button><button class="btn secondary" data-action="export-templates">↓ 导出模板包</button><button class="btn secondary" data-action="upgrade-references" '+(referenceBatchRunning||!templates.some(t=>t.referenceUpdateRequired)?'disabled':'')+'>'+(referenceBatchRunning?'正在更新识别参考…':'一键更新旧版参考')+'</button><span class="pill">'+(libraryCategory==='all'?'全部分类':esc(libraryCategory))+' · '+items.length+' 个模板</span></div>'+(mode==='template'&&queue.length?'<div class="card section-spacer"><div class="card-head"><h2>模板上传与改名</h2><small>命名格式：爆款名字+个人名字</small></div><div class="card-body" id="queue">'+queueHTML()+'</div></div><br>':'')+(items.length?'<div class="template-grid">'+items.map(t=>'<article class="template-card"><div class="template-cover">'+(t.thumbnail?'<img src="'+esc(t.thumbnail)+'" alt="'+esc(t.name)+'">':'<div class="template-original-placeholder">▷ 原视频已上传</div>')+'<span class="badge '+(t.enabled===false?'review':'')+'">'+(t.enabled===false?'已停用':t.featureReady?'已入库':t.referenceUpdateRequired?'需更新识别参考':'已入库 · 参考未就绪')+'</span></div><span class="pill">'+esc(t.category)+'</span><h3 title="'+esc(t.name)+'">'+esc(t.name)+'</h3><p>'+(t.duration?t.duration.toFixed(1)+' 秒 · ':'')+(t.frames?.length||0)+' 个参考帧 · '+day(t.createdAt)+'</p><p>'+(t.featureReady?'✓ 查重参考可用 · 模板无需审核':t.referenceUpdateRequired?'识别精度已升级，任何人均可更新参考后检测':t.preparationState==='error'?'已入库 · 自动准备未完成，可重试':'已入库 · 参考尚未就绪，可点击重试准备')+'</p><label class="template-category-control">模板分类<select data-template-category="'+esc(t.id)+'" '+(!t.canEdit||busy?'disabled':'')+'>'+categoryOptions(t.category)+'</select></label><div class="template-actions"><button class="btn ghost small" data-action="use-template" data-id="'+esc(t.id)+'" '+(t.enabled===false||!t.featureReady||busy?'disabled':'')+'>用此模板检测</button><button class="btn ghost small" data-action="rename-template" '+(!t.canEdit||busy?'disabled':'')+' data-id="'+esc(t.id)+'">改名</button>'+(!t.featureReady&&!referenceBatchRunning&&!preparingTemplateIds.has(t.id)?'<button class="btn ghost small" data-action="prepare-template" data-id="'+esc(t.id)+'">'+(t.referenceUpdateRequired?'更新识别参考':'重试准备参考')+'</button>':'')+'<button class="btn ghost small" data-action="template-detail" data-id="'+t.id+'">查看内容</button><button class="btn ghost small" data-action="toggle" '+(!t.canEdit?'disabled':'')+' data-id="'+t.id+'">'+(t.enabled===false?'启用':'停用')+'</button><button class="btn ghost small danger" data-action="delete-template" '+(!t.canEdit?'disabled':'')+' data-id="'+t.id+'">删除</button></div></article>').join('')+'</div>':'<div class="card"><div class="empty" style="padding:45px 20px"><div class="empty-icon">▤</div><strong>'+(libraryCategory==='all'?'先建立参考模板':esc(libraryCategory)+' · 暂无模板')+'</strong><p>在上方选择所属分类，上传该分类的参考视频后，组员即可选择并检测。</p></div></div>');}
function filteredRecords(){return [...records].reverse().filter(r=>(!filter||r.status===filter)&&(!search||r.name.toLowerCase().includes(search.toLowerCase())||(r.member||'').includes(search))&&(!recordCategory||r.category===recordCategory)&&(dayFilter!=='today'||day(r.createdAt)===today()));}
function recordsPage(){return pageHead('TEAM VIDEO LIBRARY','全组视频与审核结果','查看所有同事上传的视频，播放原片并查看分项审核报告。','<button class="btn secondary" data-action="export-reports">↓ 导出已加载报告</button>')+'<div class="toolbar"><input id="search" placeholder="搜索文件名、组员…" value="'+esc(search)+'" aria-label="搜索检测记录"><select id="status-filter" aria-label="筛选检测状态"><option value="">全部结果</option>'+Object.keys(label).map(k=>'<option value="'+k+'" '+(filter===k?'selected':'')+'>'+label[k]+'</option>').join('')+'</select><select id="day-filter" aria-label="筛选日期"><option value="all">全部日期</option><option value="today" '+(dayFilter==='today'?'selected':'')+'>今天</option></select><select id="record-category" aria-label="筛选模板分类">'+categoryOptions(recordCategory,'全部模板分类')+'</select><span class="pill" id="filtered-count">'+records.length+' / '+recordTotal+' 条记录</span></div><div class="card" id="records-table">'+recordTable(filteredRecords(),true)+'</div><div class="queue-actions">'+(hasMore?'<button class="btn secondary" data-action="load-more">加载更多视频</button>':'')+'<button class="btn secondary" data-action="refresh-shared">刷新</button>'+(localRecords.length?'<button class="btn ghost" data-action="local-history">本机旧记录（'+localRecords.length+'）</button>':'')+'</div><div class="split-note"><span>报告保留检测时的模板快照和规则，模板更新不改写历史结果。</span></div>';}
function guidePage(){return pageHead('TEAM SHARING GUIDE','共享视频与查重规则','所有同事共用一个视频库和模板库。')+'<div class="notice">视频与审核结果公开可见，任何拿到网址的人都能查看。上传视频前请确认可以公开。</div><div class="guide-grid"><div class="card card-body"><h3>选择模板与上传</h3><p>模板按图片中的11个文件夹名称分类。先选择分类，再选择该分类下的具体模板，最后上传待检测视频。下拉框显示全部模板及可检测/待准备/需更新/已停用状态；选择未就绪模板会自动准备参考，可先添加待检测视频，系统在登记审核前等待参考完成。也可点击准备本分类参考，一起准备该分类内所有已启用但未就绪的模板。每条队列记录保留加入时的选择，后续切换分类不会改变已排队视频。也可在模板库点击“用此模板检测”。分类只有名称不会产生参考内容，需先上传真实模板原片。模板无需审核，按“爆款名字+个人名字”命名后直接入库；爆款名字按所选分类固定，个人名字默认带入当前姓名、可修改；入库后改名也只修改个人名字。系统会自动准备查重参考，期间请保持页面打开。旧版参考可由任何人更新；点击一次会批量升级当前需要升级的旧版参考，成功后全组共用，未参与更新的模板和历史报告保持不变。</p><h3>互不打扰的个人任务</h3><p>每个页面独立保存上传队列和进度，其他组员可同时上传审核。暂停、停止或清空只作用于本页队列。开始上传时固定模板参考，审核途中其他人改名、移类、停用或删除模板不改变已开始任务的参考。每次模板上传都有独立编号，即使同名或同一原片也可分别入库；更新参考仅修改本次上传，不覆盖别人的模板。</p><h3>共享方式</h3><p>首次填写姓名后自动记住。支持批量选择视频并开始上传与审核；上传和审核独立排队，上一条审核未结束时可继续选择、拖入并上传其他视频。新加入的视频自动接入正在运行的本页队列，每条保留加入时选择的模板。已上传的条目显示等待审核，完成后自动同步结果。每条视频旁的“重新审核”会读取云端原视频，沿用对应模板并新建“重审”记录，不需要重新选择文件，原结果保留；模板参考不可用时请先更新。审核尚未开始时仍可修改该条目的BGM与无文字确认；开始审核后锁定。停止只拦住后续上传，已上传项继续完成审核。全组视频页可按姓名、文件名、状态和日期筛选，每30秒自动同步，也可手动刷新。</p><p>视频可在线播放，审核报告保留画面、字幕、花字、BGM的独立分项分数及命中模板。所有人可查看；上传者可在原浏览器删除自己的视频或启停自己的模板。清除本机存储会丢失这项管理凭据，但共享视频仍保留。</p><h3>判定规则</h3><p>先选择模板分类和对应参考视频，上传后只与该模板比较，画面、字幕、花字、BGM任一有效项不超过70%即通过；组员视频之间不互相判重。其他项目即使超过70%也不拦截；没有通过项且仍有识别缺项时待复核；所有可比项目均超过70%且没有缺项时不通过。无字幕、无花字或无BGM可由上传者明确确认。完全相同文件直接判100%。没有启用模板时不会自动通过。</p><p>画面每秒抽取约2帧，长视频在全片均匀抽取最多180帧；同时比较整帧与九宫格局部纹理，忽略缺少细节的黑边，减少局部花字遮挡造成的漏匹配；抽样画面中的文字用较高分辨率Tesseract识别，过滤低置信度碎片，按词序容忍少量识别错字及插入内容；文字须至少12词、8个不同词，且双方均覆盖至少40%的抽样画面，才可用于低分判定。按文字行中心位置分组：底部32%区域归入字幕，其余区域归入花字，再各自比较连续词片段。这是位置划分，特殊排版可能需要人工复核。BGM使用与视频同起止的纯伴奏音频，通过频谱与时间对齐比较重复片段；不转写或比较口播，也不把混合音轨当成纯BGM。此方法不提供平台官方查重率，不保证避免限流。</p></div><div class="card card-body"><h3>处理与数据</h3><p>原视频和报告保存于共享后台。画面、文字与BGM特征提取仍在上传者浏览器中运行，处理过程中不要关闭或刷新。程序不限制视频文件大小、时长、每批数量或每小时上传数量。大文件和长视频的处理速度取决于设备、网络与托管平台。</p><p>首次识别需要下载模型，依赖jsDelivr；不再下载口播模型。请先用少量真实素材验证；每日100条吞吐与误判率尚未实测。姓名是自行填写的标签，不是账号认证；系统复算比对分数，但识别特征由浏览器提交，不是不可绕过的审核系统。</p><h3>BGM与旧数据</h3><p>纯BGM片段需与视频同起止，至少3秒，时长误差不超过1秒，不设文件大小上限。可逐条选择或批量设置同一片段；只有实际使用同一片段时才批量设置。双方均确认无BGM时，该项不适用；单方确认没有内容不能产生0%分数，也不能单独触发通过。双方的原音、字幕或花字均需有可核验的比较证据。尚未提供自动人声/伴奏分离，未确认音乐本身不能触发通过，其他有效项仍可触发通过。</p><p>旧模板没有独立字幕/花字证据时，相关项目暂不计分；需更新抽样时间和文字覆盖证据后再核对；选择模板时系统会自动准备，任何组员均可更新，无需重新上传原片。旧报告保留原判定并标记旧规则，不会冒充新规则结果。</p><p>旧版保存在各浏览器的报告无法凭文件名恢复原视频。全组视频页的本机旧记录入口可查看旧报告；若要让同事播放，需重新选择原视频上传。旧模板也需要上传原片加入共享库。</p><button class="btn secondary" data-action="init-models">初始化 / 检查识别引擎</button><p id="model-state" role="status"></p></div></div><div class="card card-body section-spacer"><h2>新增截图红线提示</h2><p>自动辅助仅检查现有字幕/花字文字线索，不调用付费模型，不自动识别画面人物、Logo或原音口播。命中时显示对应规则、原文片段及修改建议，最终由人工核对。</p>'+redlineChecklist()+'</div>';}
function render(){renderMember();const indicator=$('#shared-status');if(indicator)indicator.textContent=sharedError?'共享连接失败':sharedReady?'云端共享':'连接共享区…';const r=['workbench','templates','records','guide'].includes(route())?route():'workbench';$('#crumb').textContent={workbench:'检测工作台',templates:'视频模板库',records:'全组视频',guide:'检测规则'}[r];document.querySelectorAll('[data-route]').forEach(a=>a.classList.toggle('active',a.dataset.route===r));$('#nav-count').textContent=templates.length;$('#date').textContent=new Date().toLocaleDateString('zh-CN',{timeZone:'Asia/Shanghai',year:'numeric',month:'long',day:'numeric',weekday:'short'});$('#main').innerHTML=({workbench,templates:templatesPage,records:recordsPage,guide:guidePage})[r]();const dz=$('#dropzone');if(dz){dz.ondragover=e=>{e.preventDefault();dz.classList.add('over');};dz.ondragleave=()=>dz.classList.remove('over');dz.ondrop=e=>{e.preventDefault();dz.classList.remove('over');if(busy&&mode!=='check')return toast('模板队列正在处理');if(mode!=='check'&&queue.length){if(!confirm('切换到检测将清空模板文件队列，继续吗？'))return;queue=[];}mode='check';addFiles(e.dataTransfer.files);};dz.onclick=e=>{if(!e.target.closest('button'))choose('check');};dz.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();choose('check');}};}}
function refreshQueue(){if($('#queue'))$('#queue').innerHTML=queueHTML();}
function choose(m){if(!member)return showMemberPrompt();if(busy&&(mode!=='check'||m!=='check'))return toast('视频审核中可继续添加视频；切换模板上传请等待当前队列完成');if(queue.length&&mode!==m){if(!confirm('切换操作将清空尚未处理的文件队列，继续吗？'))return;queue=[];}if(m==='check'&&!chosenTemplate())return toast('请先选择分类和对应的启用模板');if(m==='template'&&!newTemplateCategory)return toast('请先选择新模板所属分类');mode=m;$('#files').value='';$('#files').click();}
function addFiles(files){if(!member){showMemberPrompt();return toast('请先填写姓名，再选择视频');}if(busy&&mode!=='check')return toast('模板队列处理中');const selected=chosenTemplate();if(mode==='check'&&!selected)return toast('请先选择分类和对应的启用模板');if(mode==='template'&&!newTemplateCategory)return toast('请先选择新模板所属分类');const incoming=[...files];if(!incoming.length)return;if(queue.length&&queue.every(q=>q.done))queue=[];let count=0,invalid=0;for(const file of incoming){if(!file.type.startsWith('video/')&&!/\.(mp4|mov|webm)$/i.test(file.name)){invalid++;continue;}queue.push({id:crypto.randomUUID(),file,member,hitName:mode==='template'?newTemplateCategory:'',personalName:member,state:mode==='template'?'待改名后上传':'等待处理',done:false,bgmMode:'review',noSubtitle:false,noOverlay:false,category:mode==='template'?newTemplateCategory:selectedCategory,templateId:mode==='template'?null:selected.id,templateName:mode==='template'?'':selected.name});count++;}if(mode==='template')location.hash='templates';else location.hash='workbench';render();if(mode==='check'&&checkPipeline.running)checkPipeline.wake();toast('已加入 '+count+' 条视频'+(invalid?'；'+invalid+' 个文件未识别为视频，请检查格式':''));}
async function prepareTemplateReference(q){
 if(referenceTasks.has(q.sharedId))return referenceTasks.get(q.sharedId);preparingTemplateIds.add(q.sharedId);pendingPreparations++;q.preparing=true;referenceErrors.delete(q.sharedId);referenceProgress.set(q.sharedId,'正在准备所选模板参考，请保持页面打开…');
 const task=preparationTail.catch(()=>{}).then(async()=>{
  try{
   let file=q.file;if(!file){const response=await fetch(videoURL('/api/videos/'+q.sharedId));if(!response.ok)throw new Error('读取模板原视频失败');const blob=await response.blob();file=new File([blob],q.templateName||'template',{type:blob.type||'video/mp4'});}
   const f=await extract(file,p=>{referenceProgress.set(q.sharedId,p);if(selectedTemplateId===q.sharedId&&$('#reference-progress'))$('#reference-progress').textContent=p;},{forTemplate:true,mediaTimeout:60000});const result=await apiCall('/api/templates/'+q.sharedId+'/features',{method:'POST',body:{feature:f}});q.state=result.updated?'已入库 · 参考已更新':'已入库 · 参考已由他人更新';return result.updated?'updated':'skipped';
  }catch(e){q.state='参考更新失败，原参考保持不变：'+e.message;referenceErrors.set(q.sharedId,'参考准备失败：'+e.message+'。可点击本分类准备按钮重试。');return 'failed';}
  finally{q.preparing=false;pendingPreparations--;preparingTemplateIds.delete(q.sharedId);referenceProgress.delete(q.sharedId);if(mode==='template')refreshQueue();await refreshShared(false);}
 });const tracked=task.finally(()=>referenceTasks.delete(q.sharedId));referenceTasks.set(q.sharedId,tracked);preparationTail=tracked.catch(()=>{});return tracked;
}
async function ensureTemplateReference(id){
 const read=async()=>{const list=await apiCall('/api/templates');templates=list.templates;return templates.find(t=>t.id===id);};
 let t=await read();if(!t||t.enabled===false)throw new Error('所选模板已停用或不存在');
 if(!t.featureReady){const result=await prepareTemplateReference({sharedId:t.id,templateName:t.name,state:'准备参考',done:true});if(result==='failed')throw new Error(referenceErrors.get(t.id)||'模板参考准备失败');t=await read();}
 if(!t?.featureReady||t.enabled===false)throw new Error('模板参考尚未准备完成，请重试准备');return t;
}
async function updateSharedReferences(selectedId=null,category=null){
 if(referenceBatchRunning)return toast('本页正在更新参考，请保持页面打开');
 await refreshShared(false);const targets=category?categoryPreparationTargets(templates,category):referenceUpdateTargets(templates,selectedId);if(!targets.length)return toast('参考均已是最新版，无需更新');
 referenceBatchRunning=true;let updated=0,failed=0,skipped=0;const failedNames=[];
 try{for(let i=0;i<targets.length;i++){const t=targets[i];referenceUpdateMessage='正在更新识别参考 '+(i+1)+' / '+targets.length+'：'+t.name+'。更新后全组共用，请保持页面打开。';if(['templates','workbench'].includes(route()))render();const current=(await apiCall('/api/templates')).templates.find(x=>x.id===t.id);if(!current||current.featureReady||preparingTemplateIds.has(t.id)){skipped++;continue;}const result=await prepareTemplateReference({sharedId:t.id,templateName:t.name,state:'已入库',done:true});if(result==='updated')updated++;else if(result==='failed'){failed++;failedNames.push(t.name);}else skipped++;}}
 catch(e){referenceUpdateMessage='更新中断：'+e.message+'。已成功更新的保留，其余原参考不变。';toast(referenceUpdateMessage);return;}
 finally{referenceBatchRunning=false;await refreshShared(false);if(['templates','workbench'].includes(route()))render();}
 referenceUpdateMessage='参考更新完成：成功 '+updated+' 个，已更新或已删除跳过 '+skipped+' 个，失败 '+failed+' 个。'+(failed?'失败项保留原参考，可重试：'+failedNames.join('、')+'。':'')+'未参与更新的模板和历史报告保持不变。';if(['templates','workbench'].includes(route()))render();toast(referenceUpdateMessage);
}
const checkPipeline=createUploadPipeline({
 getItems:()=>queue,
 async upload(q){
  if(q.retrySourceId){q.state='读取已上传原视频';refreshQueue();await loadRetryVideo(q,q.retryVideoUrl);}
  if(!q.templateId||!q.category)throw new Error('请先为此视频选择对应模板');q.state='检查 / 准备模板参考';refreshQueue();await ensureTemplateReference(q.templateId);q.state='登记上传';refreshQueue();
  const init=await apiCall('/api/uploads',{method:'POST',body:{name:q.file.name,member:q.member,size:q.file.size,mime:q.file.type,kind:'video',category:q.category,templateId:q.templateId}});q.sharedId=init.id;q.templateSnapshotCaptured=!!init.templateSnapshotCaptured;if(init.selectedTemplateName)q.templateName=init.selectedTemplateName;
  q.state='上传中';refreshQueue();const bytes=await q.file.arrayBuffer(),sha=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',bytes)),b=>b.toString(16).padStart(2,'0')).join('');await apiCall(init.uploadUrl,{method:'PUT',headers:{'Content-Type':q.file.type||'video/mp4','X-Video-Sha256':sha},body:q.file});q.state='已上传 · 等待审核';
 },
 async audit(q){q.state='审核中';refreshQueue();const options={...q};const f=await extract(q.file,p=>{progress=q.file.name+'：'+p;const t=$('#progress-text');if(t)t.textContent=progress;},options);const result=await apiCall('/api/uploads/'+q.sharedId+'/finalize',{method:'POST',body:{feature:f}});records=records.filter(r=>r.id!==q.sharedId);records.push({...result.record,shared:true});q.state=label[result.record.status];},
 async onError(q,e,phase){q.state=(phase==='upload'?'上传失败：':'审核未完成：')+e.message;if(q.sharedId)try{const result=await apiCall('/api/uploads/'+q.sharedId+'/finalize',{method:'POST',body:{error:e.message}});records=records.filter(r=>r.id!==q.sharedId);records.push({...result.record,shared:true});}catch{}},
 onChange(state){busy=state.running;stop=state.stopping;renderMember();refreshQueue();}
});
async function run(){
 if(mode==='template')return runTemplates();if(checkPipeline.running)return;if(queue.every(q=>q.done))return toast('当前队列已全部处理');if(!member)return showMemberPrompt();
 busy=true;stop=false;render();const result=await checkPipeline.start();busy=checkPipeline.running;if(!busy)progress='';await refreshShared(true);render();toast(result.stopped?'后续上传已停止；已上传视频已完成本轮审核，其余可继续上传':'本页队列已处理完成，结果已同步到全组共享区');
}
async function runTemplates(){
 if(busy)return;if(queue.every(q=>q.done))return toast('当前队列已全部处理');if(!member){showMemberPrompt();return;}
 const isTemplate=mode==='template';if(isTemplate)for(const q of queue.filter(q=>!q.done))try{composeTemplateName(q.hitName,q.personalName);}catch(e){return toast(e.message);}
 const batchMember=member,batchQueue=queue.filter(q=>!q.done);busy=true;stop=false;render();
 for(const q of batchQueue){if(q.done)continue;if(stop)break;q.state='登记上传';progress='登记 '+q.file.name;refreshQueue();
  try{
   if(!isTemplate&&(!q.templateId||!q.category))throw new Error('请先为此视频选择对应模板');
   const init=await apiCall('/api/uploads',{method:'POST',body:{name:q.file.name,member:q.member||batchMember,size:q.file.size,mime:q.file.type,kind:isTemplate?'template':'video',category:q.category,templateId:q.templateId,...(isTemplate?{personalName:q.personalName}:{})}});q.sharedId=init.id;q.templateSnapshotCaptured=!!init.templateSnapshotCaptured;if(init.selectedTemplateName)q.templateName=init.selectedTemplateName;
   q.state='上传中';progress='正在上传原视频至公开共享区…';refreshQueue();const bytes=await q.file.arrayBuffer();const sha=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',bytes)),b=>b.toString(16).padStart(2,'0')).join('');await apiCall(init.uploadUrl,{method:'PUT',headers:{'Content-Type':q.file.type||'video/mp4','X-Video-Sha256':sha},body:q.file});q.videoUploaded=true;
   if(isTemplate){await apiCall('/api/uploads/'+q.sharedId+'/finalize',{method:'POST',body:{templateOnly:true}});q.templateName=composeTemplateName(q.hitName,q.personalName);q.state='已入库 · 自动准备参考中';q.done=true;void prepareTemplateReference(q);}
   else{q.state='检测中';refreshQueue();const f=await extract(q.file,p=>{progress=p;const t=$('#progress-text');if(t)t.textContent=p;},q);const result=await apiCall('/api/uploads/'+q.sharedId+'/finalize',{method:'POST',body:{feature:f}});const r={...result.record,shared:true};records=records.filter(x=>x.id!==r.id);records.push(r);q.state=label[r.status];q.done=true;}
  }catch(e){q.state='上传未完成：'+e.message;q.done=true;q.failed=true;if(q.sharedId&&!isTemplate){try{const result=await apiCall('/api/uploads/'+q.sharedId+'/finalize',{method:'POST',body:{error:e.message}});records.push({...result.record,shared:true});}catch{}}}
  refreshQueue();
 }
 busy=false;progress='';await refreshShared(true);render();toast(stop?'队列已停止，未处理视频仍在队列中':isTemplate?'模板已直接入库，无需审核；参考将自动准备':'处理完成，已同步到全组共享区');
}
function showTemplateRename(t){const fixed=templateNameParts(t.name,t.member,t.category);$('#detail-content').innerHTML='<h2>修改个人名字</h2><p>命名格式：爆款名字+个人名字。爆款名字固定，只修改个人名字。</p><form id="template-rename-form" data-id="'+esc(t.id)+'"><label>爆款名字（固定）<input type="text" value="'+esc(fixed.hitName)+'" readonly></label><label>个人名字（可修改）<input name="personalName" type="text" maxlength="30" value="'+esc(fixed.personalName)+'" required></label><p>上传者仍为：'+esc(t.member)+'</p><button class="btn" type="submit">保存改名</button></form>';$('#detail').showModal();}
document.addEventListener('submit',async e=>{if(e.target.id!=='template-rename-form')return;e.preventDefault();const form=e.target,button=form.querySelector('button');button.disabled=true;try{const personalName=String(new FormData(form).get('personalName')||'').trim();await apiCall('/api/templates/'+form.dataset.id,{method:'PATCH',body:{personalName}});for(const q of queue)if(q.sharedId===form.dataset.id){q.personalName=personalName;q.templateName=composeTemplateName(q.hitName,q.personalName);}$('#detail').close();await refreshShared(true);toast('个人名字已修改，爆款名字保持不变');}catch(err){toast(err.message);}finally{button.disabled=false;}});
function textEvidence(f,key,status,label){return'<h3>'+label+'</h3><div class="transcript">'+esc(status==='none'?'上传者确认没有此类文字':f[key]||'未识别到可靠内容 · 不计分')+'</div>';}
function texts(f){return textEvidence(f,'subtitles',f.subtitleStatus,'识别到的英文字幕')+textEvidence(f,'overlays',f.overlayStatus,'识别到的英文花字')+'<h3>BGM证据</h3><div class="transcript">'+esc(f.bgm?.status==='none'?'上传者确认没有BGM':f.bgm?.status==='ok'?'纯BGM片段：'+f.bgm.name+' · '+f.bgm.duration.toFixed(1)+'秒':'未提供可靠BGM证据 · 不计分')+'</div><p>口播不计分。字幕按底部32%区域划分，其余文字归入花字；特殊排版需人工复核。</p>'+(f.errors?.length?'<h3>'+(f.status==='pass'?'其他项目说明（不影响已满足的通过条件）':'未完成项目')+'</h3><div class="notice">'+f.errors.map(esc).join('<br>')+'</div>':'');}
const dimensionLabels={visual:'画面',subtitle:'字幕',overlay:'花字',bgm:'BGM'};
const dimensionScore=(c,k)=>c?.states?.[k]==='none'?'不适用':score(c?.[k]);
function report(r){const b=r.best,legacy=r.algorithm!==RULE_VERSION;$('#detail-content').innerHTML='<div class="detail-head"><div><div class="eyebrow">CHECK REPORT</div><h2>'+esc(r.name)+'</h2><p>'+esc(r.member)+' · '+dateText(r.createdAt)+'</p></div><div>查重判定：'+badge(r.status)+'</div></div>'+(legacy?'<div class="notice">旧版判定结果，仅重新整理已有分项展示，未重新分析原视频。请点击重新审核，才能执行加强证据后的判定；原结果保留。</div>':'')+(r.videoUrl?'<video class="shared-player" controls playsinline preload="metadata" src="'+esc(videoURL(r.videoUrl))+'"></video>':'<p>此记录暂无可播放的视频。</p>')+redlinePanel(r)+'<div class="big-score">'+scoreLabel(reportScore(r))+'</div><p>所选分类：'+esc(r.category||UNCATEGORIZED)+' · 对应模板：'+esc(r.selectedTemplateName||(r.comparisonScope==='selected-template'?'未选择模板':'旧记录 · 全部启用模板'))+'</p><p>'+(legacy?'历史判定分数':'最高可靠分项（不是整片重复率）')+' · '+(b?'比对模板：'+esc(b.name):'检测未完成')+'</p>'+(r.qualifying?.length?'<div class="notice">'+(legacy?'旧版判定时的低分项目':'已核验证据的低分项目')+'：'+r.qualifying.map(k=>dimensionLabels[k]).join('、')+'不超过70%。</div>':'')+'<p>此处展示最高检测分项，避免最低分掩盖其他重复内容。“未检出匹配”不代表整片完全不同；分项证据不足时不作为低分通过依据。'+(Number.isFinite(b?.highestScore)?'最高分项：'+score(b.highestScore)+'。':'')+'</p><div class="detail-grid">'+Object.entries(dimensionLabels).map(([k,name])=>'<div>'+name+'<strong>'+dimensionScore(b,k)+'</strong><small>'+esc(b?.reasons?.[k]||'')+'</small></div>').join('')+'</div><p>当前规则：画面、字幕、花字、BGM任一项不超过70%为通过，口播不计分。其他项超过70%不影响通过；未检测、单方无内容声明、无可靠画面匹配和不足量文字不视为0%。</p>'+(r.comparisons?.length?'<h3>检测时使用的模板</h3><div class="table-wrap"><table><thead><tr><th>模板</th>'+Object.values(dimensionLabels).map(name=>'<th>'+name+'</th>').join('')+'<th>判定分数</th></tr></thead><tbody>'+r.comparisons.map(c=>'<tr><td>'+esc(c.name)+'</td>'+Object.keys(dimensionLabels).map(k=>'<td>'+dimensionScore(c,k)+'</td>').join('')+'<td>'+score(c.score)+(c.complete?'':' · 存在未计分项目')+'</td></tr>').join('')+'</tbody></table></div>':'')+texts(r)+retryReviewButton(r)+'<p>算法 '+esc(r.algorithm)+' · 共享审核记录 · 不代表平台判重分数</p>';$('#detail').showModal();}
function exportReports(){const list=route()==='records'?filteredRecords():[...records].reverse();if(!list.length)return toast('当前没有可导出的检测记录');const cell=x=>'"'+String(x??'').replace(/^[=+@\-\t\r]/,"'").replace(/"/g,'""')+'"';const lines=[['文件名','组员','检测时间(北京时间)','结果','最高检测分项(%)','命中模板','画面(%)','字幕(%)','花字(%)','BGM(%)','阈值(%)','算法版本','项目说明','英文字幕','英文花字','BGM来源','模板分类','所选模板','通过项目'],...list.map(r=>[r.name,r.member,dateText(r.createdAt),label[r.status],reportScore(r)??'',r.best?.name,r.best?.visual??'',r.best?.subtitle??'',r.best?.overlay??'',r.best?.bgm??'',r.threshold,r.algorithm,(r.errors||[]).join('；'),r.subtitles,r.overlays,r.bgm?.name||r.bgm?.status||'旧规则',r.category||UNCATEGORIZED,r.selectedTemplateName||'旧记录',(r.qualifying||[]).map(k=>dimensionLabels[k]).join('、')])];download('\ufeff'+lines.map(row=>row.map(cell).join(',')).join('\r\n'),'英铁1组查重报告-'+today()+'.csv','text/csv;charset=utf-8');}
