document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;const id=b.dataset.id;try{switch(b.dataset.action){case'library-category':libraryCategory=b.dataset.category;if(libraryCategory!=='all')newTemplateCategory=libraryCategory;render();break;case'add-in-category':newTemplateCategory=selectedCategory;libraryCategory=selectedCategory;break;case'use-template':{if(busy&&mode!=='check')return toast('请等待模板上传完成');const t=templates.find(t=>t.id===id&&t.enabled!==false&&t.featureReady!==false);if(!t)return toast('模板已停用或不存在');selectedCategory=t.category;selectedTemplateId=t.id;location.hash='workbench';render();break;}case'pick-bgm':if(!queue[Number(id)]?.auditing){bgmTarget=queue[Number(id)]?.id;$('#bgm-file').value='';$('#bgm-file').click();}break;case'batch-bgm':{bgmTarget='all';$('#bgm-file').value='';$('#bgm-file').click();}break;case'batch-no-bgm':{for(const q of queue)if(!q.done&&!q.auditing){q.bgmMode='none';delete q.bgmFile;}refreshQueue();}break;case'retry-review':void retryReview(id);break;case'refresh-shared':await refreshShared(true);break;case'load-more':await loadMore();break;case'local-history':$('#detail-content').innerHTML='<h2>本机旧记录</h2><p>这些是旧版本仅保存在当前浏览器中的报告，不在共享区。需要原视频重新上传才能让组员播放。</p>'+recordTable([...localRecords].reverse());$('#detail').showModal();break;case'delete-shared':if(confirm('从共享区删除此视频与报告？此操作不能恢复。')){await apiCall('/api/uploads/'+id,{method:'DELETE'});await refreshShared(true);}break;case'switch-member':showMemberPrompt();break;case'choose':choose('check');break;case'add-template':choose('template');break;case'run':await run();break;case'stop':stop=true;if(mode==='check')checkPipeline.stop();refreshQueue();break;case'remove-queue':{const q=queue[Number(id)];if(q&&(!q.started||q.done))queue.splice(Number(id),1);refreshQueue();break;}case'clear-queue':if(busy)return toast('请先停止后续上传并等待已上传项审核完成');queue=[];render();break;case'export-reports':exportReports();break;case'export-templates':if(!templates.length)return toast('请先添加模板');download(JSON.stringify({format:VERSION,exportedAt:new Date().toISOString(),templates},null,2),'英铁1组模板包-'+today()+'.json','application/json');break;case'import':if(busy)return toast('请先完成当前检测');$('#import-file').value='';$('#import-file').click();break;case'toggle':{if(busy)return toast('请等待队列完成后修改模板');const t=templates.find(t=>t.id===id);await apiCall('/api/templates/'+id,{method:'PATCH',body:{enabled:t.enabled===false}});await refreshShared(true);break;}case'delete-template':{if(busy)return toast('请等待队列完成');const t=templates.find(t=>t.id===id);if(confirm('从全组共享库删除模板「'+t.name+'」和原视频？此操作不能恢复。')){await apiCall('/api/uploads/'+id,{method:'DELETE'});await refreshShared(true);}break;}case'report':{const r=records.find(r=>r.id===id)||localRecords.find(r=>r.id===id);report(r?.localOnly?r:await apiCall('/api/records/'+id));break;}case'rename-template':{const t=templates.find(t=>t.id===id);if(t?.canEdit)showTemplateRename(t);break;}case'prepare-category-references':void updateSharedReferences(null,selectedCategory);break;case'prepare-template':void updateSharedReferences(id);break;case'upgrade-references':void updateSharedReferences();break;case'template-detail':{const t=templates.find(t=>t.id===id);$('#detail-content').innerHTML='<h2>'+esc(t.name)+'</h2><p>'+(t.duration?t.duration.toFixed(1)+' 秒 · ':'')+(t.frames?.length||0)+' 个参考样本 · 模板无需审核</p>'+texts(t);$('#detail').showModal();break;}case'init-models':if(busy)return toast('当前队列正在使用识别引擎');b.disabled=true;try{await initialize(p=>{if($('#model-state'))$('#model-state').textContent=p;});if($('#model-state'))$('#model-state').textContent='✓ 字幕/花字引擎已就绪，BGM使用本机音频指纹，不加载语音模型。';toast('识别引擎就绪');}catch(err){if($('#model-state'))$('#model-state').textContent='初始化失败：'+err.message;}finally{b.disabled=false;}break;}}catch(err){toast('操作失败：'+err.message);}});
